// Tiny bundler for exactly these three local modules; emits the ModuleLoader artifact.
// No package installation, eval, external imports or duplicate React runtime.
import { readFile, writeFile } from 'node:fs/promises';
const source = async (name) => readFile(new URL(name, import.meta.url), 'utf8');
const field = (await source('./water-field.js')).replace(/^export class /m, 'class ');
const renderer = (await source('./ocean-renderer.js')).replace(/^export function /m, 'function ');
const entry = (await source('./client-entry.js')).replace(/^import .+ from '.+';\n/gm, '');
const output = `// Generated by node build.js — edit client-entry.js / water-field.js / ocean-renderer.js.\n(() => {\n'use strict';\n${field}\n${renderer}\n${entry}\n})();\n`;
await writeFile(new URL('./client.js', import.meta.url), output);
console.log('Built client.js (self-contained ModuleLoader artifact)');
